begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values ('c1000000-0000-0000-0000-000000000001','fields@example.test'); insert into public.organizations(id,name) values ('c2000000-0000-0000-0000-000000000001','Fields'); insert into public.organization_members(organization_id,user_id,role) values ('c2000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','owner');
set local role authenticated; set local request.jwt.claim.sub = 'c1000000-0000-0000-0000-000000000001';
select lives_ok($$select public.apply_template('c2000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001')$$,'Energy template is usable without seed');
insert into public.customers(id,organization_id,owner_id,created_by,first_name,last_name) values ('c3000000-0000-0000-0000-000000000001','c2000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','Fields','Customer');
insert into public.contracts(id,organization_id,customer_id,created_by,contract_type_id,status) select 'c4000000-0000-0000-0000-000000000001','c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001',id,'active' from public.contract_types where key='electricity';
select lives_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_number,created_by) select 'c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',d.id,'number',3500,'c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions d join public.contract_types t on t.id=d.contract_type_id where d.key='annual_consumption' and t.key='electricity'$$,'Energy consumption uses a typed numeric value');
select throws_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_number,created_by) select 'c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',d.id,'number',-1,'c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions d join public.contract_types t on t.id=d.contract_type_id where d.key='annual_consumption' and t.key='electricity'$$,'23514',null,'Energy consumption cannot be negative');
select throws_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_number,created_by) select 'c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',d.id,'number','NaN'::numeric,'c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions d join public.contract_types t on t.id=d.contract_type_id where d.key='annual_consumption' and t.key='electricity'$$,'23514',null,'Nonfinite custom numeric rejected');
select throws_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_number,created_by) select 'c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',d.id,'text',3,'c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions d join public.contract_types t on t.id=d.contract_type_id where d.key='meter_number' and t.key='electricity'$$,'23514',null,'Wrong typed storage column rejected');
select throws_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_text,value_number,created_by) select 'c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',d.id,'text','M1',3,'c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions d join public.contract_types t on t.id=d.contract_type_id where d.key='meter_number' and t.key='electricity'$$,'23514',null,'Multiple populated typed columns rejected');
select throws_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_text,created_by) select 'c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',d.id,'text','Wrong scope','c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions d join public.contract_types t on t.id=d.contract_type_id where d.key='market_location_id' and t.key='gas'$$,'23514',null,'Gas-only field cannot attach to electricity contract');
select throws_ok($$update public.contracts set contract_type_id=(select id from public.contract_types where key='gas') where id='c4000000-0000-0000-0000-000000000001'$$,'23514',null,'Changing contract type cannot invalidate populated scoped fields');
select throws_ok($$update public.custom_field_definitions set contract_type_id=(select id from public.contract_types where key='gas') where key='annual_consumption' and contract_type_id=(select id from public.contract_types where key='electricity')$$,'23514',null,'Field scope cannot drift');
select throws_ok($$update public.custom_field_definitions set data_type='text' where key='annual_consumption'$$,'23514',null,'Definition data type cannot drift');
select throws_ok($$delete from public.custom_field_definitions where key='annual_consumption' and contract_type_id=(select id from public.contract_types where key='electricity')$$,'23503',null,'Used definition cannot cascade-delete values');
select lives_ok($$update public.custom_field_definitions set is_active=false where key='annual_consumption'$$,'Used definition can be retired');
select results_eq($$select count(*) from public.contract_custom_field_values$$,array[1::bigint],'Retiring a definition preserves history');
select throws_ok($$update public.contract_custom_field_values set value_number=4500$$,'23514',null,'Retired definition values cannot be edited');
select lives_ok($$update public.custom_field_definitions set is_active=true where key='annual_consumption'$$,'Definition can be reactivated');
select throws_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_number,created_by) select 'c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001',d.id,'number',4500,'c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions d join public.contract_types t on t.id=d.contract_type_id where d.key='annual_consumption' and t.key='electricity'$$,'23505',null,'Duplicate entity-definition value rejected');
select throws_ok($$insert into public.custom_field_definitions(organization_id,entity_type,key,label,data_type,config) values ('c2000000-0000-0000-0000-000000000001','customer','bad','Bad','number','{"min":"no"}')$$,'23514',null,'Malformed numeric bounds rejected');
select throws_ok($$insert into public.custom_field_definitions(organization_id,entity_type,key,label,data_type,config) values ('c2000000-0000-0000-0000-000000000001','customer','bad','Bad','number','{"min":10,"max":1}')$$,'23514',null,'Inverted numeric bounds rejected');
insert into public.custom_field_definitions(id,organization_id,entity_type,key,label,data_type) values ('c5000000-0000-0000-0000-000000000001','c2000000-0000-0000-0000-000000000001','customer','typed_1','Typed','text');
select lives_ok($$insert into public.customer_custom_field_values(organization_id,customer_id,custom_field_definition_id,data_type,value_text,created_by) values ('c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000001','text','hello','c1000000-0000-0000-0000-000000000001')$$,'Valid text custom field round-trips');
insert into public.custom_field_definitions(id,organization_id,entity_type,key,label,data_type) values ('c5000000-0000-0000-0000-000000000002','c2000000-0000-0000-0000-000000000001','customer','typed_2','Typed','number');
select lives_ok($$insert into public.customer_custom_field_values(organization_id,customer_id,custom_field_definition_id,data_type,value_number,created_by) values ('c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000002','number',10.5,'c1000000-0000-0000-0000-000000000001')$$,'Valid number custom field round-trips');
insert into public.custom_field_definitions(id,organization_id,entity_type,key,label,data_type) values ('c5000000-0000-0000-0000-000000000003','c2000000-0000-0000-0000-000000000001','customer','typed_3','Typed','boolean');
select lives_ok($$insert into public.customer_custom_field_values(organization_id,customer_id,custom_field_definition_id,data_type,value_boolean,created_by) values ('c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000003','boolean',false,'c1000000-0000-0000-0000-000000000001')$$,'Valid boolean custom field round-trips');
insert into public.custom_field_definitions(id,organization_id,entity_type,key,label,data_type) values ('c5000000-0000-0000-0000-000000000004','c2000000-0000-0000-0000-000000000001','customer','typed_4','Typed','date');
select lives_ok($$insert into public.customer_custom_field_values(organization_id,customer_id,custom_field_definition_id,data_type,value_date,created_by) values ('c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000004','date','2026-01-01','c1000000-0000-0000-0000-000000000001')$$,'Valid date custom field round-trips');
insert into public.custom_field_definitions(id,organization_id,entity_type,key,label,data_type) values ('c5000000-0000-0000-0000-000000000005','c2000000-0000-0000-0000-000000000001','customer','typed_5','Typed','timestamptz');
select lives_ok($$insert into public.customer_custom_field_values(organization_id,customer_id,custom_field_definition_id,data_type,value_timestamptz,created_by) values ('c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000005','timestamptz','2026-01-01 12:00:00+00','c1000000-0000-0000-0000-000000000001')$$,'Valid timestamptz custom field round-trips');
select throws_ok($$insert into public.customer_custom_field_values(organization_id,customer_id,custom_field_definition_id,data_type,value_text,created_by) select 'c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001',id,'text','wrong','c1000000-0000-0000-0000-000000000001' from public.custom_field_definitions where key='meter_number' limit 1$$,'23503',null,'Contract definition cannot attach to customer');
select throws_ok($$insert into public.contract_custom_field_values(organization_id,contract_id,custom_field_definition_id,data_type,value_text,created_by) values ('c2000000-0000-0000-0000-000000000001','c4000000-0000-0000-0000-000000000001','c5000000-0000-0000-0000-000000000001','text','wrong','c1000000-0000-0000-0000-000000000001')$$,'23503',null,'Customer definition cannot attach to contract');
select throws_ok($$update public.customer_custom_field_values set data_type='number', value_text=null, value_number=10 where custom_field_definition_id='c5000000-0000-0000-0000-000000000001'$$,'23503',null,'Value data type must match definition');
set constraints all immediate;
select lives_ok($$update public.custom_field_definitions set is_required=true where id='c5000000-0000-0000-0000-000000000001'$$,'Populated field may become required');
select throws_ok($$delete from public.customer_custom_field_values where custom_field_definition_id='c5000000-0000-0000-0000-000000000001'$$,'23514',null,'Required customer value cannot be deleted');
select throws_ok($$update public.customer_custom_field_values set value_text=' ' where custom_field_definition_id='c5000000-0000-0000-0000-000000000001'$$,'23514',null,'Required text cannot become blank');
select throws_ok($$insert into public.customers(organization_id,owner_id,created_by,first_name,last_name) values ('c2000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','Missing','Field')$$,'23514',null,'Customer without required value fails integrity');
select throws_ok($$insert into public.custom_field_definitions(organization_id,entity_type,key,label,data_type,is_required) values ('c2000000-0000-0000-0000-000000000001','customer','missing','Missing','text',true)$$,'23514',null,'Cannot introduce missing required field over existing customers');
select lives_ok($$update public.custom_field_definitions set is_required=true where key='annual_consumption'$$,'Applicable populated contract field may become required');
select throws_ok($$delete from public.contract_custom_field_values$$,'23514',null,'Required contract value cannot be deleted');
select throws_ok($$insert into public.contracts(organization_id,customer_id,created_by,contract_type_id,status) select 'c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001',id,'active' from public.contract_types where key='gas'$$,'23514',null,'Required scoped field enforced for new gas contract');
set constraints all deferred;
select lives_ok($$insert into public.customers(id,organization_id,owner_id,created_by,first_name,last_name) values ('c3000000-0000-0000-0000-000000000002','c2000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','Atomic','Customer'); insert into public.customer_custom_field_values(organization_id,customer_id,custom_field_definition_id,data_type,value_text,created_by) values ('c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000002','c5000000-0000-0000-0000-000000000001','text','present','c1000000-0000-0000-0000-000000000001'); set constraints all immediate;$$,'Entity and required values can be saved atomically');
select lives_ok($$delete from public.customers where id='c3000000-0000-0000-0000-000000000002'$$,'Hard delete is compatible with required-field constraints');
select lives_ok($$update public.contract_types set is_active=false where key='gas'$$,'Contract type may be retired');
select throws_ok($$insert into public.contracts(organization_id,customer_id,created_by,contract_type_id,status) select 'c2000000-0000-0000-0000-000000000001','c3000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001',id,'active' from public.contract_types where key='gas'$$,'23503',null,'New contracts cannot use inactive types');
reset role;
select results_eq($$select count(*) from public.template_contract_types$$,array[2::bigint],'Template application leaves catalog unchanged');
select results_eq($$select count(*) from public.organization_templates where organization_id='c2000000-0000-0000-0000-000000000001'$$,array[1::bigint],'Template installation provenance retained');
select * from finish(); rollback;
